import React, { useState, useCallback } from 'react';
import styled from '@emotion/styled';
import { Layout, NavTree, theme } from '@atlantis/shared';
import type { NavEntry } from '@atlantis/shared';
import { useQuotes, ALL_INDEX_SYMBOLS, ALL_SECTOR_SYMBOLS, REGIONS } from './hooks';
import MarketOverview from './components/MarketOverview';
import RegionPanel from './components/RegionPanel';
import SectorHeatmap from './components/SectorHeatmap';
import MarketCalendar from './components/MarketCalendar';

const SECTIONS: NavEntry[] = [
  {
    id: 'markets',
    name: 'Markets',
    icon: 'activity',
    children: [
      { id: 'overview',  name: 'Overview',      icon: 'layout-grid' },
      { id: 'americas',  name: 'Americas',      icon: 'globe'       },
      { id: 'europe',    name: 'Europe',        icon: 'globe'       },
      { id: 'asia',      name: 'Asia Pacific',  icon: 'globe'       },
    ],
  },
  {
    id: 'analysis',
    name: 'Analysis',
    icon: 'bar-chart-2',
    children: [
      { id: 'sectors',  name: 'Sectors',        icon: 'layers'      },
      { id: 'calendar', name: 'Good/Bad Days',  icon: 'calendar'    },
    ],
  },
];

const Content = styled.div`
  padding: ${theme.spacing.xl};
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.xl};
  max-width: 1400px;
  width: 100%;
`;

const Section = styled.section`
  scroll-margin-top: ${theme.spacing.lg};
`;

const Panel = styled.div`
  background: ${theme.colors.surface};
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.lg};
  padding: ${theme.spacing.lg};
`;

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [activeSection, setActiveSection] = useState<string | null>(null);

  // Single batch fetch for all index + sector quotes
  const allSymbols = [...ALL_INDEX_SYMBOLS, ...ALL_SECTOR_SYMBOLS];
  const { quotes, loading, error } = useQuotes(allSymbols, 4 * 60 * 60 * 1000);

  const handleSelect = useCallback((entry: NavEntry) => {
    setActiveSection(entry.id);
    document.getElementById(entry.id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, []);

  const sidebar = (
    <NavTree entries={SECTIONS} activeId={activeSection} onSelect={handleSelect} />
  );

  return (
    <Layout title="StockPulse" sidebar={sidebar} activeId={activeSection} topBarRight={topBarRight}>
      <Content>
        <Section id="overview">
          <Panel>
            <MarketOverview quotes={quotes} loading={loading} error={error} />
          </Panel>
        </Section>

        {REGIONS.map((region) => (
          <Section key={region.id} id={region.id}>
            <Panel>
              <RegionPanel region={region} quotes={quotes} loading={loading} />
            </Panel>
          </Section>
        ))}

        <Section id="sectors">
          <Panel>
            <SectorHeatmap quotes={quotes} loading={loading} />
          </Panel>
        </Section>

        <Section id="calendar">
          <Panel>
            <MarketCalendar />
          </Panel>
        </Section>
      </Content>
    </Layout>
  );
}
